(function(){(()=>{"use strict";const e=(t,o,i,a,s,r,n)=>({g:t,p:o,n:i,f:a,how:s,ex:r,...n?{fig:n}:{}});window.PhysicaRankSetsJee={chapter:"Sets, Relations and Functions",secs:["Sets and their representation","Operations, laws and Venn diagrams","Counting with sets","Relations: types and counting","Functions: one-one, onto and counting","Composition and inverse","Domain, range and graphs","Even, odd, periodic, [x] and \uFF5Bx\uFF5D"],table:[["x \u2208 A, x \u2209 A","x belongs to A, x does not belong to A"],["A \u2286 B, A \u2282 B","A is a subset of B, A is a proper subset of B"],["\u2205, U","the empty set, the universal set"],["A \u222A B, A \u2229 B","union (in A or B or both), intersection (in both)"],["A \u2212 B, A\u2032","elements of A not in B, complement of A (U \u2212 A)"],["A \u0394 B","symmetric difference (A \u2212 B) \u222A (B \u2212 A)"],["n(A), P(A)","number of elements of A, power set (set of all subsets)"],["A \xD7 B","Cartesian product: all ordered pairs (a, b)"],["aRb, R\u2286A\xD7B","a is related to b, a relation from A to B"],["f: A \u2192 B","function from A (domain) to B (codomain)"],["g\u2218f, f\u207B\xB9","composite g(f(x)), inverse function"],["[x], \uFF5Bx\uFF5D, |x|","greatest integer \u2264 x, fractional part x \u2212 [x], modulus"]],formulas:[e("Sets and their representation",1,"Representation, types and equality","roster form \uFF5B1, 2, 3\uFF5D \xB7 set-builder form \uFF5Bx : x \u2208 \u2115, x < 4\uFF5D \xB7 \u2205 has no element and is a subset of every set \xB7 singleton has one element \xB7 A = B \u21D4 A \u2286 B and B \u2286 A \xB7 \u2115 \u2282 \u2124 \u2282 \u211A \u2282 \u211D \xB7 A \u2286 A for every A \xB7 \uFF5B\u2205\uFF5D is not empty: it has one element","Convert set-builder form to roster form by listing the values that satisfy the condition. Check every condition (integer, positive, inequality) before you count.","\uFF5Bx : x \u2208 \u2124, x\xB2 < 10\uFF5D = \uFF5B\u22123, \u22122, \u22121, 0, 1, 2, 3\uFF5D, so it has 7 elements. The set \uFF5B(x, y) : x\xB2 + y\xB2 = 25, x, y \u2208 \u2124\uFF5D has 12 elements: (\xB15, 0), (0, \xB15), (\xB13, \xB14), (\xB14, \xB13)."),e("Sets and their representation",1,"Subsets and power set","n(A) = n \u21D2 number of subsets = 2^(n) \xB7 proper subsets = 2^(n) \u2212 1 \xB7 non-empty proper subsets = 2^(n) \u2212 2 \xB7 n(P(A)) = 2^(n) \xB7 subsets with exactly k elements = \u207FC_k \xB7 subsets containing a fixed element = 2^(n\u22121) \xB7 if A \u2286 X \u2286 B, n(A) = a, n(B) = b: number of X = 2^(b\u2212a)","Each element is either in a subset or out of it: two choices per element, so 2^(n). Fixed elements remove their choice.","A = \uFF5B1, 2\uFF5D, B = \uFF5B1, 2, 3, 4, 5, 6\uFF5D: the sets X with A \u2286 X \u2286 B number 2^(6\u22122) = 16. A set of 4 elements has 16 subsets, 15 proper ones and 14 non-empty proper ones."),e("Sets and their representation",1,"Cartesian product and ordered pairs","n(A \xD7 B) = n(A) \xD7 n(B) \xB7 (a, b) = (c, d) \u21D4 a = c and b = d \xB7 A \xD7 B \u2260 B \xD7 A unless A = B (or one is empty) \xB7 A \xD7 (B \u2229 C) = (A \xD7 B) \u2229 (A \xD7 C) \xB7 A \xD7 (B \u222A C) = (A \xD7 B) \u222A (A \xD7 C) \xB7 n(A \xD7 A) = n\xB2 \xB7 number of subsets of A \xD7 B = 2^(mn)","The order inside a pair matters. A subset of A \xD7 B is a relation from A to B, so the number of relations is the number of subsets.","n(A) = 3, n(B) = 2: A \xD7 B has 6 ordered pairs and 2\u2076 = 64 relations from A to B."),e("Sets and their representation",2,"Intervals and modulus inequalities","(a, b) = \uFF5Bx : a < x < b\uFF5D \xB7 [a, b] includes the ends \xB7 |x| < a \u21D4 \u2212a < x < a \xB7 |x| > a \u21D4 x < \u2212a or x > a (a > 0) \xB7 |x \u2212 c| \u2264 r \u21D4 c \u2212 r \u2264 x \u2264 c + r \xB7 \u211D \u2212 \u211A = irrational numbers","Write the condition as a statement about x, then as an interval. Use a round bracket for < and a square bracket for \u2264.","|x \u2212 2| \u2264 3 \u21D4 \u22123 \u2264 x \u2212 2 \u2264 3 \u21D4 x \u2208 [\u22121, 5]."),e("Operations, laws and Venn diagrams",1,"Union, intersection, difference, complement","A \u222A B = \uFF5Bx : x \u2208 A or x \u2208 B\uFF5D \xB7 A \u2229 B = \uFF5Bx : x \u2208 A and x \u2208 B\uFF5D \xB7 A \u2212 B = A \u2229 B\u2032 \xB7 A\u2032 = U \u2212 A \xB7 A \u0394 B = (A \u2212 B) \u222A (B \u2212 A) \xB7 n(A \u0394 B) = n(A) + n(B) \u2212 2n(A \u2229 B) \xB7 A \u2286 B \u21D4 A \u222A B = B \u21D4 A \u2229 B = A \u21D4 B\u2032 \u2286 A\u2032 \xB7 A, B are disjoint if A \u2229 B = \u2205",'Rewrite every difference as A \u2229 B\u2032 and every set condition as "and", "or", "not" before you work.',"A = \uFF5B1, 2, 3, 4\uFF5D, B = \uFF5B3, 4, 5\uFF5D: A \u2212 B = \uFF5B1, 2\uFF5D, B \u2212 A = \uFF5B5\uFF5D, A \u0394 B = \uFF5B1, 2, 5\uFF5D, and n(A \u0394 B) = 4 + 3 \u2212 2 \xD7 2 = 3."),e("Operations, laws and Venn diagrams",1,"De Morgan\u2019s laws","(A \u222A B)\u2032 = A\u2032 \u2229 B\u2032 \xB7 (A \u2229 B)\u2032 = A\u2032 \u222A B\u2032 \xB7 (A \u222A B \u222A C)\u2032 = A\u2032 \u2229 B\u2032 \u2229 C\u2032 \xB7 A \u2212 (B \u222A C) = (A \u2212 B) \u2229 (A \u2212 C) \xB7 A \u2212 (B \u2229 C) = (A \u2212 B) \u222A (A \u2212 C) \xB7 A \u2229 (B \u2212 C) = (A \u2229 B) \u2212 (A \u2229 C)",'To take a complement, change \u222A into \u2229, \u2229 into \u222A, and complement each set. This is the usual way to count "neither".',"U = \uFF5B1, \u2026, 10\uFF5D, A = \uFF5B1, 2, 3, 4\uFF5D, B = \uFF5B3, 4, 5, 6\uFF5D: (A \u222A B)\u2032 = \uFF5B7, 8, 9, 10\uFF5D = A\u2032 \u2229 B\u2032, and (A \u2229 B)\u2032 has 10 \u2212 2 = 8 elements = n(A\u2032 \u222A B\u2032)."),e("Operations, laws and Venn diagrams",1,"Laws of sets","A \u222A B = B \u222A A, A \u2229 B = B \u2229 A \xB7 associative \xB7 A \u2229 (B \u222A C) = (A \u2229 B) \u222A (A \u2229 C) \xB7 A \u222A (B \u2229 C) = (A \u222A B) \u2229 (A \u222A C) \xB7 A \u222A A = A, A \u2229 A = A \xB7 A \u222A \u2205 = A, A \u2229 U = A, A \u222A U = U, A \u2229 \u2205 = \u2205 \xB7 A \u222A A\u2032 = U, A \u2229 A\u2032 = \u2205, (A\u2032)\u2032 = A \xB7 absorption: A \u222A (A \u2229 B) = A, A \u2229 (A \u222A B) = A \xB7 A \u222A (A\u2032 \u2229 B) = A \u222A B","Use these to simplify a long expression: expand with the distributive law, then cancel with A \u222A A\u2032 = U and A \u2229 A\u2032 = \u2205.","A = \uFF5B1, 2\uFF5D, B = \uFF5B2, 3\uFF5D, U = \uFF5B1, 2, 3, 4\uFF5D: A\u2032 \u2229 B = \uFF5B3\uFF5D, so A \u222A (A\u2032 \u2229 B) = \uFF5B1, 2, 3\uFF5D = A \u222A B."),e("Operations, laws and Venn diagrams",1,"Region names in a Venn diagram","only A = A \u2212 B = A \u2229 B\u2032 \xB7 only B = B \u2212 A \xB7 both = A \u2229 B \xB7 exactly one = A \u0394 B \xB7 neither = A\u2032 \u2229 B\u2032 = (A \u222A B)\u2032 \xB7 inside the rectangle U every element is in exactly one region \xB7 for A \u2286 B the circle of A lies inside the circle of B","Draw the diagram, mark each region with a letter, and write the sentence as a list of regions. Then add the numbers.",'"Students who play cricket but not football" is the region A \u2212 B. "Students who play neither" is the region outside both circles.',"stven2"),e("Operations, laws and Venn diagrams",2,"Counting pairs of subsets","S has n elements. Ordered pairs (A, B) of subsets: all pairs 4^(n) \xB7 A \u2286 B: 3^(n) \xB7 A \u2229 B = \u2205: 3^(n) \xB7 A \u222A B = S: 3^(n) \xB7 each element has 3 choices in each of the last three cases","Decide how many places an element may occupy: for A \u2286 B an element is in neither, in B only, or in both (3 places).","n = 3: there are 4\xB3 = 64 pairs in all and 3\xB3 = 27 pairs with A \u2286 B, 27 with A \u2229 B = \u2205 and 27 with A \u222A B = S."),e("Counting with sets",1,"Two sets","n(A \u222A B) = n(A) + n(B) \u2212 n(A \u2229 B) \xB7 only A = n(A) \u2212 n(A \u2229 B) \xB7 exactly one of the two = n(A) + n(B) \u2212 2n(A \u2229 B) \xB7 neither = N \u2212 n(A \u222A B), N the total \xB7 n(A \u2229 B) \u2264 min(n(A), n(B)) \xB7 n(A \u2229 B) \u2265 max(0, n(A) + n(B) \u2212 N)","Write the formula first, put in the known numbers, and solve for the unknown. Never add n(A) and n(B) alone: the overlap is counted twice.","In a class 40 like tea and 30 like coffee, 55 like at least one. Both: 40 + 30 \u2212 55 = 15. Exactly one: 55 \u2212 15 = 40.","stven2"),e("Counting with sets",1,"Three sets","n(A \u222A B \u222A C) = n(A) + n(B) + n(C) \u2212 n(A \u2229 B) \u2212 n(B \u2229 C) \u2212 n(A \u2229 C) + n(A \u2229 B \u2229 C) \xB7 n(A\u2032 \u2229 B\u2032 \u2229 C\u2032) = N \u2212 n(A \u222A B \u222A C) \xB7 seven regions in the diagram: a, b, c (one set only), x, y, z (two sets only), t (all three)","Subtract the three pairs, then add back the triple, because it was added 3 times and subtracted 3 times.","n(A) = 30, n(B) = 25, n(C) = 20, n(A \u2229 B) = 10, n(B \u2229 C) = 8, n(A \u2229 C) = 6, n(A \u2229 B \u2229 C) = 3: union = 75 \u2212 24 + 3 = 54. The regions are a = 17, b = 10, c = 9, x = 7, y = 5, z = 3, t = 3, and they add up to 54.","stven3"),e("Counting with sets",1,"Exactly one, exactly two, at least two","\u03A31 = n(A) + n(B) + n(C), \u03A32 = sum of the three pair intersections, T = n(A \u2229 B \u2229 C) \xB7 exactly one = \u03A31 \u2212 2\u03A32 + 3T \xB7 exactly two = \u03A32 \u2212 3T \xB7 exactly three = T \xB7 at least two = \u03A32 \u2212 2T \xB7 at least one = \u03A31 \u2212 \u03A32 + T",'Pair intersections include the centre region three times, so take 3T off to get "exactly two". Check your answer by adding the cases: one + two + three = union.',"Use the numbers above: \u03A31 = 75, \u03A32 = 24, T = 3. Exactly one: 75 \u2212 48 + 9 = 36. Exactly two: 24 \u2212 9 = 15. Exactly three: 3. At least two: 24 \u2212 6 = 18. Check: 36 + 15 + 3 = 54.","stven3"),e("Counting with sets",1,'Percentages and "neither" problems','take N = 100 when percentages are given \xB7 n(A\u2032 \u2229 B\u2032) = N \u2212 n(A \u222A B) \xB7 n(A\u2032 \u2229 B) = n(B) \u2212 n(A \u2229 B) \xB7 n(A\u2032 \u222A B\u2032) = N \u2212 n(A \u2229 B) \xB7 "at least one" = union, "none" = complement of the union',"Translate each phrase into a region or a complement, and work with the total N.","60 % read paper A, 50 % read paper B and 20 % read both: 90 % read at least one, so 10 % read neither and 40 % read exactly one."),e("Counting with sets",2,"Greatest and least overlap","n(A) = a, n(B) = b, total N: least n(A \u2229 B) = max(0, a + b \u2212 N) \xB7 greatest n(A \u2229 B) = min(a, b) \xB7 three sets: least n(A \u2229 B \u2229 C) = max(0, a + b + c \u2212 2N) \xB7 greatest = min(a, b, c)","For the least overlap push the sets apart until the union is N. Use the complements: the sets that miss the sets cannot exceed N altogether.","N = 100, a = 70, b = 60: n(A \u2229 B) lies between 30 and 60. N = 10, sets of 7, 6, 7 elements: the triple intersection can be anything from 0 to 6."),e("Relations: types and counting",1,"Relation, domain, range, inverse","a relation R from A to B is any subset of A \xD7 B \xB7 domain = first coordinates \xB7 range = second coordinates (a subset of B, the codomain) \xB7 R\u207B\xB9 = \uFF5B(b, a) : (a, b) \u2208 R\uFF5D \xB7 relations from A to B: 2^(mn) \xB7 relations on A: 2^(n\xB2)","Make the list of pairs from the rule, then read the domain and range off the list.","R = \uFF5B(x, y) : x + 2y = 8, x, y \u2208 \u2115\uFF5D = \uFF5B(2, 3), (4, 2), (6, 1)\uFF5D. Domain \uFF5B2, 4, 6\uFF5D, range \uFF5B1, 2, 3\uFF5D, and R\u207B\xB9 = \uFF5B(3, 2), (2, 4), (1, 6)\uFF5D."),e("Relations: types and counting",1,"Reflexive, symmetric, transitive, antisymmetric","reflexive: (a, a) \u2208 R for every a \xB7 symmetric: (a, b) \u2208 R \u21D2 (b, a) \u2208 R \xB7 transitive: (a, b), (b, c) \u2208 R \u21D2 (a, c) \u2208 R \xB7 antisymmetric: (a, b) and (b, a) \u2208 R \u21D2 a = b \xB7 to disprove a property, one counter-example is enough \xB7 R is symmetric \u21D4 R = R\u207B\xB9","Test reflexive first (look for a missing (a, a)), then symmetric (find a pair without its reverse), then transitive (chain two pairs and look for the shortcut).","On \uFF5B1, 2, 3\uFF5D let R = \uFF5B(1,1), (2,2), (3,3), (1,2), (2,1), (2,3), (3,2)\uFF5D. R is reflexive and symmetric, but not transitive: (1, 2) and (2, 3) are in R and (1, 3) is not."),e("Relations: types and counting",1,"Equivalence relation and classes","equivalence = reflexive + symmetric + transitive \xB7 the classes of an equivalence relation split A into disjoint parts that together make A \xB7 a \u223C b \u21D4 a and b are in the same class \xB7 smallest equivalence relation on A: the identity \uFF5B(a, a)\uFF5D \xB7 largest: A \xD7 A \xB7 x R y \u21D4 x \u2212 y divisible by m on \u2124 gives m classes (the residues 0, \u2026, m \u2212 1)","To show a relation is an equivalence prove all three properties. To count equivalence relations count the ways to split A into groups.","x R y \u21D4 3 divides x \u2212 y on \u2124 has the 3 classes \uFF5B\u2026, \u22123, 0, 3, \u2026\uFF5D, \uFF5B\u2026, \u22122, 1, 4, \u2026\uFF5D, \uFF5B\u2026, \u22121, 2, 5, \u2026\uFF5D."),e("Relations: types and counting",1,"Counting relations on a set of n elements","all relations: 2^(n\xB2) \xB7 reflexive: 2^(n\xB2\u2212n) \xB7 symmetric: 2^(n(n+1)/2) \xB7 reflexive and symmetric: 2^(n(n\u22121)/2) \xB7 antisymmetric: 2^(n) \xD7 3^(n(n\u22121)/2) \xB7 asymmetric: 3^(n(n\u22121)/2) \xB7 equivalence relations = number of partitions: 1, 2, 5, 15, 52 for n = 1 \u2026 5 \xB7 transitive: no simple formula","The n\xB2 pairs split into n diagonal pairs and n(n \u2212 1)/2 pairs of mirror images. Reflexive fixes the diagonal; symmetric makes the mirror pairs go together.","For n = 3: 512 relations, 64 reflexive, 64 symmetric, 8 reflexive and symmetric, 216 antisymmetric, 27 asymmetric and 5 equivalence relations. For n = 4 there are 15 equivalence relations, and 5 of them contain (1, 2)."),e("Relations: types and counting",1,"Standard relations to remember",'"is parallel to" (lines): equivalence \xB7 "is perpendicular to": symmetric only \xB7 "x = y": equivalence \xB7 "x \u2264 y" on \u211D: reflexive, antisymmetric, transitive (not symmetric) \xB7 "x < y": transitive and antisymmetric only \xB7 "x divides y" on \u2115: reflexive, antisymmetric, transitive \xB7 "|x \u2212 y| \u2264 1" on \u2124: reflexive and symmetric, not transitive \xB7 "is similar (congruent) to" for triangles: equivalence','Remember these ten and most "find the type" questions are done. Check the one that is new with a counter-example.',"|x \u2212 y| \u2264 1 on \u2124: (0, 1) and (1, 2) are in the relation, but |0 \u2212 2| = 2 > 1, so (0, 2) is not: not transitive."),e("Relations: types and counting",2,"Combining relations","if R and S are equivalence relations on A, R \u2229 S is an equivalence relation \xB7 R \u222A S need not be transitive \xB7 R\u207B\xB9 of an equivalence relation is the same relation \xB7 symmetric relations on n = 3 containing a given pair (a, b) with a \u2260 b: 2^5 = 32 \xB7 equivalence relations on 3 elements containing (1, 2): 2","Check the three properties of the intersection pair by pair. For the union look for a chain that leaves A.","On \uFF5B1, 2, 3\uFF5D: R has classes \uFF5B1, 2\uFF5D, \uFF5B3\uFF5D and S has classes \uFF5B1\uFF5D, \uFF5B2, 3\uFF5D. R \u2229 S is the identity, an equivalence relation. R \u222A S contains (1, 2) and (2, 3) but not (1, 3), so it is not transitive."),e("Functions: one-one, onto and counting",1,"Function, domain, codomain, range","a function assigns to each x of the domain exactly one y of the codomain \xB7 range = set of all values f(x) \u2286 codomain \xB7 vertical line test: a vertical line meets the graph at most once \xB7 f = g needs the same domain, codomain and rule \xB7 number of functions from A to B = n(B)^(n(A))","Check the two conditions: every input has an output, and no input has two. Find the range by working out the values, not by looking at the codomain.","f(x) = \u221A(9 \u2212 x\xB2): the domain is [\u22123, 3] and the range is [0, 3]. From a set of 2 elements to a set of 3 elements there are 3\xB2 = 9 functions."),e("Functions: one-one, onto and counting",1,"One-one (injective) functions","f(a) = f(b) \u21D2 a = b \xB7 equivalent: a \u2260 b \u21D2 f(a) \u2260 f(b) \xB7 a strictly increasing or strictly decreasing function is one-one \xB7 an even function (not on one point) is many-one \xB7 polynomial of even degree on \u211D is many-one \xB7 n(A) = m, n(B) = n: one-one functions = n!/(n \u2212 m)! if m \u2264 n, and 0 if m > n","Try f(a) = f(b) and solve. If a second solution a \u2260 b exists, it is many-one. For a counting question place the images one after the other: n, then n \u2212 1, \u2026","f(x) = x\xB2 on \u211D: f(2) = f(\u22122), many-one. From 3 elements to 5 elements: 5 \xD7 4 \xD7 3 = 60 one-one functions; to 4 elements: 24."),e("Functions: one-one, onto and counting",1,"Onto (surjective) functions","onto \u21D4 range = codomain \xB7 onto functions from an m-set to a 2-set: 2^(m) \u2212 2 \xB7 to a 3-set: 3^(m) \u2212 3\xD72^(m) + 3 \xB7 general: \u03A3(\u22121)^(k) \u207FC_k (n \u2212 k)^(m) \xB7 for two finite sets of equal size: one-one \u21D4 onto \u21D4 bijective \xB7 bijections from an n-set to itself: n!","Onto means every element of the codomain is hit. For counting, subtract the functions that miss some element (inclusion\u2013exclusion).","From 5 elements to 2: 2\u2075 \u2212 2 = 30. From 4 elements to 3: 3\u2074 \u2212 3 \xD7 2\u2074 + 3 = 36. From 5 elements to 3: 3\u2075 \u2212 3 \xD7 2\u2075 + 3 = 150."),e("Functions: one-one, onto and counting",1,"Counting functions with a condition","f: A \u2192 B, n(A) = m, n(B) = n \xB7 all: n^(m) \xB7 constant: n \xB7 strictly increasing (order kept): \u207FC_m \xB7 non-decreasing: \u207F\u207A\u1D50\u207B\xB9C_m \xB7 functions of A to itself with f(a) = a for one fixed a: n^(n\u22121) \xB7 idempotent f(f(x)) = f(x) on 3 elements: 10","A strictly increasing function is fixed once you choose which m values of B are used, so count the choices of m values.","\uFF5B1, 2, 3\uFF5D \u2192 \uFF5B1, \u2026, 5\uFF5D: 125 functions in all, 60 one-one, 10 strictly increasing, 35 non-decreasing. \uFF5B1, 2, 3, 4\uFF5D \u2192 \uFF5B1, 2, 3, 4\uFF5D with f(1) = 1: 4\xB3 = 64.","stmap"),e("Functions: one-one, onto and counting",1,"The four kinds of function","one-one and onto: bijection (inverse exists) \xB7 one-one and into \xB7 many-one and onto \xB7 many-one and into \xB7 x\xB3 on \u211D: bijection \xB7 e\u02E3: \u211D \u2192 \u211D is one-one and into (range (0, \u221E)) \xB7 x\xB2: \u211D \u2192 \u211D is many-one and into \xB7 sin x: \u211D \u2192 \u211D is many-one and into \xB7 to make a function onto, make the codomain equal to the range","Decide one-one by the graph (horizontal line) and onto by comparing the range with the stated codomain. A question may change the codomain only to test onto.","f(x) = x\xB2: \u211D \u2192 \u211D is neither one-one nor onto. f: [0, \u221E) \u2192 [0, \u221E) with the same rule is a bijection.","stmap"),e("Functions: one-one, onto and counting",1,"Horizontal line test","one-one \u21D4 every line y = c meets the graph at most once \xB7 onto \u21D4 every line y = c with c in the codomain meets the graph at least once \xB7 a continuous one-one function on an interval is strictly monotonic \xB7 the derivative f\u2032(x) keeps one sign \u21D2 one-one","Draw a rough graph, then sweep a horizontal line. Count the hits for each height.","f(x) = x\xB3 \u2212 3x meets y = 0 at x = 0, \u221A3 and \u2212\u221A3, so it is many-one; it takes every real value, so it is onto \u211D.","stgrf"),e("Composition and inverse",1,"Composition of functions","(g\u2218f)(x) = g(f(x)) \xB7 f acts first \xB7 domain of g\u2218f: x in the domain of f with f(x) in the domain of g \xB7 g\u2218f \u2260 f\u2218g in general \xB7 h\u2218(g\u2218f) = (h\u2218g)\u2218f \xB7 f, g one-one \u21D2 g\u2218f one-one \xB7 f, g onto \u21D2 g\u2218f onto \xB7 g\u2218f one-one \u21D2 f one-one \xB7 g\u2218f onto \u21D2 g onto","Substitute the whole of f(x) in place of x in g. Do the inner function first, and check the domain at the end.","f(x) = 2x + 1, g(x) = x\xB2: (g\u2218f)(3) = 49 and (f\u2218g)(3) = 19. (g\u2218f)(x) = (2x + 1)\xB2, (f\u2218g)(x) = 2x\xB2 + 1, and they are equal when 2x\xB2 + 4x = 0, that is x = 0 or x = \u22122.","stcmp"),e("Composition and inverse",2,"Domain of a composite","dom(g\u2218f) = \uFF5Bx \u2208 dom f : f(x) \u2208 dom g\uFF5D \xB7 simplifying the formula may hide a restriction \xB7 f\u2218f: apply f twice and keep both conditions","Write the domain of the inner function first, then add the condition that its value lies in the domain of the outer function.","f(x) = \u221Ax, g(x) = x\xB2 \u2212 1: (f\u2218g)(x) = \u221A(x\xB2 \u2212 1), domain |x| \u2265 1. (g\u2218f)(x) = x \u2212 1 but its domain is x \u2265 0, not all of \u211D."),e("Composition and inverse",1,"Inverse function","f\u207B\xB9 exists \u21D4 f is a bijection \xB7 f\u207B\xB9(f(x)) = x and f(f\u207B\xB9(y)) = y \xB7 to find f\u207B\xB9: put y = f(x), solve for x in y, then swap \xB7 dom(f\u207B\xB9) = range(f), range(f\u207B\xB9) = dom(f) \xB7 (f\u207B\xB9)\u207B\xB9 = f \xB7 (g\u2218f)\u207B\xB9 = f\u207B\xB9\u2218g\u207B\xB9 \xB7 the graph of f\u207B\xB9 is the reflection of the graph of f in the line y = x \xB7 (a, b) on f \u21D4 (b, a) on f\u207B\xB9","Solve y = f(x) for x. Restrict the domain and codomain if the function is not a bijection. In (g\u2218f)\u207B\xB9 the order reverses.","f(x) = (2x + 1)/(x \u2212 3), x \u2260 3: y(x \u2212 3) = 2x + 1 gives x = (3y + 1)/(y \u2212 2), so f\u207B\xB9(y) = (3y + 1)/(y \u2212 2). Check: f(4) = 9 and f\u207B\xB9(9) = 28/7 = 4.","stinv"),e("Composition and inverse",2,"Self-inverse functions","f\u2218f = identity \u21D4 f = f\u207B\xB9 \xB7 f(x) = (ax + b)/(cx \u2212 a) is self-inverse \xB7 f(x) = a \u2212 x, f(x) = 1/x, f(x) = k/x are self-inverse \xB7 the graph is symmetric about y = x \xB7 for an increasing f: f(x) = f\u207B\xB9(x) \u21D4 f(x) = x \xB7 self-inverse functions on 3 elements: 4","Test f(f(x)) = x. For x = f\u207B\xB9(x) on an increasing function solve f(x) = x, which is easier.","f(x) = (x + 1)/(x \u2212 1): f(f(x)) = x, so f = f\u207B\xB9. On \uFF5B1, 2, 3\uFF5D the identity and the three swaps give 4 functions with f(f(x)) = x."),e("Domain, range and graphs",1,"Finding the domain","denominator \u2260 0 \xB7 even root: expression under it \u2265 0 \xB7 log: argument > 0 (and base > 0, \u2260 1) \xB7 sin\u207B\xB9 x, cos\u207B\xB9 x: \u22121 \u2264 x \u2264 1 \xB7 tan x: x \u2260 (2k + 1)\u03C0/2 \xB7 [x] and |x| are defined for all x \xB7 for a sum or product take the intersection of the domains \xB7 f(x)^(g(x)): base > 0","List each condition as a separate inequality and take the common part. Factorise the quadratic and use a sign line.","f(x) = \u221A(x\xB2 \u2212 5x + 6): (x \u2212 2)(x \u2212 3) \u2265 0, so x \u2264 2 or x \u2265 3."),e("Domain, range and graphs",1,"Finding the range","method 1: put y = f(x), solve for x, and keep the y for which x is real and in the domain \xB7 method 2: use bounds such as sin x \u2208 [\u22121, 1], x\xB2 \u2265 0, a sin x + b cos x \u2208 [\u2212\u221A(a\xB2 + b\xB2), \u221A(a\xB2 + b\xB2)] \xB7 complete the square for a quadratic \xB7 for a one-one continuous f read the range from the two ends","Choose the shortest method: bounds for trigonometric and square expressions, discriminant for ratios of quadratics.","x\xB2 \u2212 4x + 7 = (x \u2212 2)\xB2 + 3 has the range [3, \u221E). The range of 3 sin x + 4 cos x is [\u22125, 5]. x\xB2/(1 + x\xB2) = 1 \u2212 1/(1 + x\xB2) has the range [0, 1)."),e("Domain, range and graphs",2,"Range by the discriminant","y = (ax\xB2 + bx + c)/(px\xB2 + qx + r): write it as a quadratic in x, with x real so the discriminant \u2265 0 \xB7 check separately the y where the coefficient of x\xB2 is 0 \xB7 for y = x/(1 + x\xB2): yx\xB2 \u2212 x + y = 0, D = 1 \u2212 4y\xB2 \u2265 0","The coefficient of x\xB2 may vanish at some y; solve that case separately.","y = x/(1 + x\xB2): D = 1 \u2212 4y\xB2 \u2265 0 gives \u22121/2 \u2264 y \u2264 1/2, and y = 0 is reached at x = 0, so the range is [\u22121/2, 1/2]."),e("Domain, range and graphs",1,"Transformations of graphs","y = f(x) + a: up by a \xB7 y = f(x + a): left by a \xB7 y = \u2212f(x): flip in the x-axis \xB7 y = f(\u2212x): flip in the y-axis \xB7 y = |f(x)|: reflect the part below the x-axis upwards \xB7 y = f(|x|): keep x \u2265 0 and reflect it in the y-axis \xB7 y = af(x): stretch in y \xB7 y = f(ax): compress in x","Move the vertex or a key point first, then draw the shape. The sign inside the bracket moves the graph the opposite way from what it seems.","y = (x \u2212 2)\xB2 + 3 is y = x\xB2 shifted 2 right and 3 up, with the vertex at (2, 3). y = |x \u2212 1| has its vertex at (1, 0)."),e("Domain, range and graphs",2,"Standard graphs and their ranges","x\xB2: range [0, \u221E), even, many-one \xB7 x\xB3: \u211D, odd, one-one \xB7 1/x: \u211D \u2212 \uFF5B0\uFF5D, odd, one-one \xB7 \u221Ax: [0, \u221E), one-one \xB7 |x|: [0, \u221E), even \xB7 e\u02E3: (0, \u221E), one-one \xB7 ln x: \u211D, domain (0, \u221E), one-one \xB7 sin x: [\u22121, 1], odd, periodic \xB7 sgn x: \uFF5B\u22121, 0, 1\uFF5D","Learn the shapes with their symmetry and range; most questions ask for one of these properties.","ln x and e\u02E3 are inverses: the domain (0, \u221E) of ln x is the range of e\u02E3, and the range \u211D of ln x is the domain of e\u02E3."),e("Even, odd, periodic, [x] and \uFF5Bx\uFF5D",1,"Even and odd functions","even: f(\u2212x) = f(x), the graph is symmetric about the y-axis \xB7 odd: f(\u2212x) = \u2212f(x), the graph is symmetric about the origin \xB7 the domain must be symmetric about 0 \xB7 f(0) = 0 for an odd function defined at 0 \xB7 even \xD7 even and odd \xD7 odd are even; even \xD7 odd is odd \xB7 every f = (f(x) + f(\u2212x))/2 (even) + (f(x) \u2212 f(\u2212x))/2 (odd) \xB7 the only function that is both is f = 0","Replace x by \u2212x and compare with f(x) and \u2212f(x). For a sum of terms test each term.","f(x) = x\xB3 + x\xB2: f(2) = 12 and f(\u22122) = \u22124, neither even nor odd; the even part is x\xB2 and the odd part is x\xB3. f(x) = ln(x + \u221A(x\xB2 + 1)) is odd, since f(x) + f(\u2212x) = ln 1 = 0."),e("Even, odd, periodic, [x] and \uFF5Bx\uFF5D",1,"Periodic functions","f(x + T) = f(x), least positive T is the period \xB7 sin(ax + b), cos(ax + b), sec, cosec: 2\u03C0/|a| \xB7 tan(ax + b), cot(ax + b): \u03C0/|a| \xB7 |sin x|, |cos x|, sin\xB2x, cos\xB2x, |tan x|: \u03C0 \xB7 period of f(x) + g(x) is the LCM of the periods (when it exists) \xB7 LCM of a/b and c/d = LCM(a, c)/HCF(b, d) \xB7 if f has the period T, f(ax + b) has the period T/|a|","Find the period of each term, then the least common multiple. If the ratio of the periods is irrational the sum is not periodic.","sin(x/2) + cos(x/3): periods 4\u03C0 and 6\u03C0, so 12\u03C0. sin(\u03C0x) + cos(\u03C0x/2): periods 2 and 4, so 4. tan 3x has the period \u03C0/3."),e("Even, odd, periodic, [x] and \uFF5Bx\uFF5D",2,"Special periods","|sin x| + |cos x|: \u03C0/2 \xB7 sin\u2074x + cos\u2074x = 1 \u2212 \xBDsin\xB22x: \u03C0/2 \xB7 \uFF5Bx\uFF5D = x \u2212 [x]: 1 \xB7 constant function: every real number is a period, no least period \xB7 [x], x, x\xB2 are not periodic \xB7 f(x + a) = f(x \u2212 a) \u21D2 period 2a","Rewrite the expression with a double angle first when powers appear. Then use the standard rule.","sin\u2074x + cos\u2074x repeats after \u03C0/2: for example the value at x = 0 is 1 and the value at x = \u03C0/2 is also 1, and sin\xB22x has the period \u03C0/2."),e("Even, odd, periodic, [x] and \uFF5Bx\uFF5D",1,"Greatest integer function [x]","[x] = n for n \u2264 x < n + 1 (n an integer) \xB7 [x] \u2264 x < [x] + 1 \xB7 [x + n] = [x] + n for an integer n \xB7 [x] + [\u2212x] = 0 if x is an integer, \u22121 otherwise \xB7 domain \u211D, range \u2124 \xB7 the graph is a staircase (left end closed, right end open) \xB7 many-one, not onto \u211D, not periodic \xB7 [\u22122.3] = \u22123, [2.9] = 2","Reduce an equation in [x] to an equation for the integer value n, then turn n \u2264 x < n + 1 into an interval.","[x]\xB2 \u2212 5[x] + 6 = 0 \u21D2 [x] = 2 or 3 \u21D2 2 \u2264 x < 4. The range of [sin x] is \uFF5B\u22121, 0, 1\uFF5D: \u22121 for sin x < 0, 0 for 0 \u2264 sin x < 1 and 1 at sin x = 1.","stgi"),e("Even, odd, periodic, [x] and \uFF5Bx\uFF5D",1,"Fractional part \uFF5Bx\uFF5D","\uFF5Bx\uFF5D = x \u2212 [x] \xB7 0 \u2264 \uFF5Bx\uFF5D < 1 \xB7 range [0, 1) \xB7 period 1 \xB7 \uFF5Bx\uFF5D = 0 \u21D4 x is an integer \xB7 \uFF5Bx\uFF5D + \uFF5B\u2212x\uFF5D = 1 if x is not an integer, 0 if it is \xB7 \uFF5Bx + n\uFF5D = \uFF5Bx\uFF5D for an integer n \xB7 [x] + \uFF5Bx\uFF5D = x","Write x as its integer part plus the fraction. For negative x do not drop the sign: \uFF5B\u22121.3\uFF5D = \u22121.3 \u2212 (\u22122) = 0.7.","\uFF5B\u22121.3\uFF5D = 0.7 and \uFF5B1.3\uFF5D = 0.3, so \uFF5Bx\uFF5D + \uFF5B\u2212x\uFF5D = 1. \uFF5Bx\uFF5D is not even or odd and it repeats with period 1.","stgi"),e("Even, odd, periodic, [x] and \uFF5Bx\uFF5D",2,"Modulus, signum and combinations","|x| = x if x \u2265 0, \u2212x if x < 0 \xB7 |x| = \u221A(x\xB2) \xB7 |a + b| \u2264 |a| + |b| \xB7 |a b| = |a||b| \xB7 sgn x = 1, 0, \u22121 for x > 0, = 0, < 0 \xB7 f(x) = [x] + [\u2212x] is an even function \xB7 [x] \u2212 x = \u2212\uFF5Bx\uFF5D \xB7 |x| is even, sgn x is odd","To handle |x| split the line at the point where the expression inside is zero and write each part without the modulus.","f(x) = [x] + [\u2212x] gives f(\u2212x) = [\u2212x] + [x] = f(x), so f is even; it takes the values 0 and \u22121 only.")],look:["Subsets 2^n; proper 2^n \u2212 1; A \u2286 X \u2286 B gives 2^(b\u2212a); n(A \xD7 B) = mn; relations A \u2192 B: 2^(mn)","A \u2212 B = A \u2229 B\u2032; De Morgan: (A \u222A B)\u2032 = A\u2032 \u2229 B\u2032, (A \u2229 B)\u2032 = A\u2032 \u222A B\u2032; n(A \u0394 B) = n(A) + n(B) \u2212 2n(A \u2229 B)","n(A \u222A B) = n(A) + n(B) \u2212 n(A \u2229 B); three sets: \u03A31 \u2212 \u03A32 + T; exactly two = \u03A32 \u2212 3T; exactly one = \u03A31 \u2212 2\u03A32 + 3T","Reflexive: all (a, a); symmetric: every pair has its reverse; transitive: no missing shortcut; equivalence = all three","Relations on n elements: 2^(n\xB2) all, 2^(n\xB2\u2212n) reflexive, 2^(n(n+1)/2) symmetric, 2^(n(n\u22121)/2) reflexive and symmetric, 3^(n(n\u22121)/2) asymmetric; equivalence 1, 2, 5, 15, 52","m \u2192 n functions: n^m all, n!/(n\u2212m)! one-one, 2^m \u2212 2 onto a 2-set, 3^m \u2212 3\xD72^m + 3 onto a 3-set, \u207FC_m strictly increasing","One-one: horizontal line cuts once at most; onto: range = codomain; bijection: inverse exists, graph is a mirror image in y = x","(g\u2218f)(x) = g(f(x)), f first; not commutative; (g\u2218f)\u207B\xB9 = f\u207B\xB9\u2218g\u207B\xB9; f self-inverse \u21D4 f(f(x)) = x","Domain: denominator \u2260 0, root \u2265 0, log > 0; range: solve for x, complete the square, use bounds; |sin x|: period \u03C0; [x]: staircase, \uFF5Bx\uFF5D = x \u2212 [x] with period 1"],notes:[{h:"Sets and their representation",items:["A set is a well-defined collection; write it in roster form or set-builder form.","\u2205 is a subset of every set and every set is a subset of itself.","A set of n elements has 2^n subsets and 2^n \u2212 1 proper subsets.","\u2115 \u2282 \u2124 \u2282 \u211A \u2282 \u211D; irrational numbers are \u211D \u2212 \u211A.","|x| < a means \u2212a < x < a; |x| > a means x < \u2212a or x > a.","Equal sets have the same elements; \uFF5B\u2205\uFF5D has one element, \u2205 has none."]},{h:"Operations on sets",items:["A \u222A B has the elements in A or B or both; A \u2229 B has the elements in both.","A \u2212 B = A \u2229 B\u2032: in A, not in B.","The complement A\u2032 is always taken inside a universal set U.","A \u0394 B has the elements in exactly one of the two sets.","A \u2286 B is the same as A \u222A B = B and the same as A \u2229 B = A.","Disjoint sets have an empty intersection and n(A \u222A B) = n(A) + n(B)."]},{h:"Laws and De Morgan",items:["Union and intersection are commutative and associative.","Each distributes over the other: A \u2229 (B \u222A C) = (A \u2229 B) \u222A (A \u2229 C).","De Morgan: (A \u222A B)\u2032 = A\u2032 \u2229 B\u2032 and (A \u2229 B)\u2032 = A\u2032 \u222A B\u2032.","A \u222A A\u2032 = U and A \u2229 A\u2032 = \u2205.","A \u222A (A\u2032 \u2229 B) = A \u222A B is the most useful simplification.","To prove a set identity show both inclusions, or check each region of a Venn diagram."]},{h:"Venn diagrams and counting",items:["Draw a rectangle for U and one circle for each set.","Two circles make four regions: A only, A \u2229 B, B only, and neither.","Three circles make eight regions: seven inside and one outside.","n(A \u222A B) = n(A) + n(B) \u2212 n(A \u2229 B).","For three sets subtract the pairs and add the triple back.","Fill the diagram from the centre outwards: first the triple, then the pairs, then the single sets."],fig:"stven2"},{h:"Three-set counting",items:["\u03A31 is the sum of the three set sizes, \u03A32 the sum of the three pair intersections, T the triple.","At least one: \u03A31 \u2212 \u03A32 + T.","Exactly one: \u03A31 \u2212 2\u03A32 + 3T.","Exactly two: \u03A32 \u2212 3T.","At least two: \u03A32 \u2212 2T.","The region count adds up: one + two + three = union."],fig:"stven3"},{h:"Relations",items:["A relation from A to B is a subset of A \xD7 B.","The number of relations on an n-set is 2^(n\xB2).","Reflexive: every (a, a) is present; symmetric: each pair comes with its reverse.","Transitive: if (a, b) and (b, c) are present then (a, c) is present.","An equivalence relation splits the set into disjoint classes.",'Parallel lines and equal remainders mod m are equivalence relations; "<" and "divides" are not symmetric.']},{h:"Counting relations",items:["Reflexive on n elements: 2^(n\xB2\u2212n).","Symmetric: 2^(n(n+1)/2).","Reflexive and symmetric: 2^(n(n\u22121)/2).","Antisymmetric: 2^n \xD7 3^(n(n\u22121)/2); asymmetric: 3^(n(n\u22121)/2).","Equivalence relations on n elements = number of partitions: 1, 2, 5, 15, 52.","On 3 elements: 512 relations, 64 reflexive, 64 symmetric, 5 equivalence."]},{h:"Functions: one-one and onto",items:["A function gives exactly one output for every input in the domain.","One-one: different inputs give different outputs; onto: every element of the codomain is hit.","From an m-set to an n-set: n^m functions and n!/(n \u2212 m)! one-one functions.","Onto counts: 2^m \u2212 2 to a 2-set, 3^m \u2212 3\xD72^m + 3 to a 3-set.","For finite sets of equal size one-one and onto go together.","Horizontal line test: one-one if it meets the graph at most once."],fig:"stmap"},{h:"Composition and inverse",items:["(g\u2218f)(x) = g(f(x)); f is applied first.","Composition is associative but usually not commutative.","The domain of g\u2218f needs f(x) to lie in the domain of g.","f\u207B\xB9 exists only for a bijection; solve y = f(x) for x and swap.","(g\u2218f)\u207B\xB9 = f\u207B\xB9\u2218g\u207B\xB9, in the reverse order.","The graph of f\u207B\xB9 is the mirror image of the graph of f in y = x."],fig:"stcmp"},{h:"Domain, range, even/odd, periodic, [x] and \uFF5Bx\uFF5D",items:["Domain: denominator not zero, even root not negative, log argument positive.","Range: solve for x, complete the square, or use bounds like |sin x| \u2264 1.","Even f(\u2212x) = f(x); odd f(\u2212x) = \u2212f(x); the domain must be symmetric.","Periods: sin x, cos x: 2\u03C0; tan x, |sin x|, sin\xB2x: \u03C0; period of a sum is the LCM.","[x] is the greatest integer \u2264 x: a staircase with range \u2124; \uFF5Bx\uFF5D = x \u2212 [x] with range [0, 1) and period 1.","[x] + [\u2212x] = \u22121 and \uFF5Bx\uFF5D + \uFF5B\u2212x\uFF5D = 1 when x is not an integer."],fig:"stgi"}],asked:[{t:"Number of elements, subsets and power set",what:"A set is given in roster form or by a rule. Find the number of its elements, subsets, proper subsets or sets between two given sets.",steps:["List the elements that satisfy the rule and count them.","A set of n elements has 2^n subsets, 2^n \u2212 1 proper subsets.","For A \u2286 X \u2286 B the number is 2^(n(B) \u2212 n(A))."],ex:"\uFF5Bx \u2208 \u2124 : x\xB2 < 10\uFF5D has 7 elements and 128 subsets.",tp:"sets"},{t:"Set operations and De Morgan\u2019s laws",what:"Two or three sets are given, or a set identity. Find A \u2212 B, A \u0394 B, a complement, or decide which identity is true.",steps:["Write A \u2212 B as A \u2229 B\u2032.","Use De Morgan to take a complement.","Check an identity with a small example or a Venn diagram."],ex:"A = \uFF5B1, 2, 3, 4\uFF5D, B = \uFF5B3, 4, 5\uFF5D: A \u0394 B = \uFF5B1, 2, 5\uFF5D.",tp:"sets",fig:"stven2"},{t:"Two-set counting (tea, coffee, cricket, football)",what:"A group likes two things. Some numbers are given. Find those who like both, only one, or neither.",steps:["Write n(A \u222A B) = n(A) + n(B) \u2212 n(A \u2229 B).","Find the unknown from the formula.","Neither = total \u2212 union."],ex:"40, 30 and 55 in the union: 15 like both.",tp:"sets",fig:"stven2"},{t:"Three-set counting with exactly one, exactly two",what:"Three sets with pair and triple intersections are given. Find the union, the number in exactly one or exactly two sets, or the number in none.",steps:["Union = \u03A31 \u2212 \u03A32 + T.","Exactly two = \u03A32 \u2212 3T.","Exactly one = \u03A31 \u2212 2\u03A32 + 3T."],ex:"30, 25, 20; 10, 8, 6; 3: union 54, exactly one 36.",tp:"sets",fig:"stven3"},{t:"Greatest and least value of an overlap",what:"Sizes of two or three sets in a population are given. Find the least or the greatest number of elements in the intersection.",steps:["Least n(A \u2229 B) = max(0, a + b \u2212 N).","Greatest = min(a, b).","Three sets: least triple = max(0, a + b + c \u2212 2N)."],ex:"N = 100, a = 70, b = 60: between 30 and 60.",tp:"sets"},{t:"Pairs of subsets and special subsets",what:"S has n elements. Count ordered pairs (A, B) with A \u2286 B, A \u2229 B = \u2205 or A \u222A B = S, or subsets with a stated property.",steps:["Give each element its possible places.","Multiply over the n elements.","Fixed elements are not counted again."],ex:"n = 3, A \u2286 B: 3\xB3 = 27 pairs.",tp:"sets"},{t:"Cartesian product and number of relations",what:"Sizes of A and B are given. Find n(A \xD7 B), the number of relations, or a statement on products.",steps:["n(A \xD7 B) = mn.","Relations from A to B: 2^(mn).","Use A \xD7 (B \u2229 C) = (A \xD7 B) \u2229 (A \xD7 C)."],ex:"n(A) = 3, n(B) = 2: 6 pairs and 64 relations.",tp:"rel"},{t:"Domain and range of a relation",what:"A relation is given by a rule on \u2115 or on a small set. Write it as pairs, find the domain and range, or the inverse.",steps:["List the pairs.","Domain = first coordinates, range = second.","Inverse: swap each pair."],ex:"x + 2y = 8 on \u2115: domain \uFF5B2, 4, 6\uFF5D, range \uFF5B1, 2, 3\uFF5D.",tp:"rel"},{t:"Type of a given relation",what:"A relation is given on a set of numbers or lines. Decide which of reflexive, symmetric, transitive, antisymmetric it is.",steps:["Test reflexive: is every (a, a) present?","Test symmetric: has every pair its reverse?","Test transitive: chain two pairs."],ex:"|x \u2212 y| \u2264 1 on \u2124: reflexive, symmetric, not transitive.",tp:"rel"},{t:"Proving an equivalence relation and finding the classes",what:'A rule such as x \u2212 y divisible by m, or "same remainder", is given. Prove it is an equivalence relation or find the class of an element.',steps:["Show reflexive, symmetric and transitive.","The class of a is the set of all elements related to a.","The classes are disjoint and cover the set."],ex:"x \u2212 y divisible by 3 on \u2124: 3 classes.",tp:"rel"},{t:"Number of reflexive, symmetric or equivalence relations",what:"A set with n elements is given. Count the relations that are reflexive, symmetric, reflexive and symmetric, antisymmetric or equivalence.",steps:["Split the n\xB2 pairs into n diagonal and n(n \u2212 1)/2 mirror pairs.","Apply the formula for the type.","Equivalence: count the partitions."],ex:"n = 3: reflexive 64, symmetric 64, equivalence 5.",tp:"rel"},{t:"Combining relations",what:"Two relations are given. Decide whether the union, intersection or inverse of equivalence relations is an equivalence relation.",steps:["Intersection of equivalence relations is one.","Union may fail transitivity: look for a chain.","The inverse of an equivalence relation is itself."],ex:"Classes \uFF5B1,2\uFF5D,\uFF5B3\uFF5D and \uFF5B1\uFF5D,\uFF5B2,3\uFF5D: the union is not transitive.",tp:"rel"},{t:"Is it a function, and its domain and range",what:"A rule or a set of pairs is given. Decide if it is a function and find the domain and the range.",steps:["Each input needs exactly one output.","Domain: conditions on the rule.","Range: solve for x or use bounds."],ex:"\u221A(9 \u2212 x\xB2): domain [\u22123, 3], range [0, 3].",tp:"dr"},{t:"One-one and onto: type of a given function",what:"A function f: A \u2192 B is given by a rule. Decide whether it is one-one, onto, both or neither.",steps:["One-one: f(a) = f(b) \u21D2 a = b, or the horizontal line test.","Onto: range = codomain.","Change the codomain to make it onto."],ex:"x\xB2 on \u211D is neither; on [0, \u221E) \u2192 [0, \u221E) it is both.",tp:"func",fig:"stgrf"},{t:"Number of functions of a given kind",what:"Two finite sets are given. Count all functions, one-one, onto, strictly increasing or functions with a stated condition.",steps:["All: n^m; one-one: n!/(n \u2212 m)!.","Onto: subtract the functions that miss an element.","Increasing: choose m values: \u207FC_m."],ex:"\uFF5B1..5\uFF5D \u2192 \uFF5B1,2,3\uFF5D: 243 in all, 150 onto.",tp:"func",fig:"stmap"},{t:"Composition of two functions",what:"Two rules f and g are given. Find (g\u2218f)(x), a value, the points where g\u2218f = f\u2218g, or its domain.",steps:["Put f(x) in place of x in g.","Simplify and keep the domain condition.","Solve g\u2218f = f\u2218g as an equation."],ex:"f = 2x + 1, g = x\xB2: g\u2218f = f\u2218g at x = 0, \u22122.",tp:"func",fig:"stcmp"},{t:"Inverse of a function",what:"A bijection is given. Find f\u207B\xB9 or a value of it, or a relation between f\u207B\xB9 and f.",steps:["Put y = f(x).","Solve for x in terms of y.","Swap x and y and state the domain."],ex:"f = (2x + 1)/(x \u2212 3): f\u207B\xB9(y) = (3y + 1)/(y \u2212 2).",tp:"func",fig:"stinv"},{t:"Domain of a function",what:"A rule with a root, a fraction, a logarithm or an inverse trigonometric function is given. Find the domain.",steps:["List each restriction.","Solve each inequality.","Take the common part."],ex:"\u221A(x\xB2 \u2212 5x + 6): x \u2264 2 or x \u2265 3.",tp:"dr"},{t:"Range of a function",what:"A rational, quadratic or trigonometric expression is given. Find the range.",steps:["Complete the square or use a known bound.","For a ratio solve for x and use D \u2265 0.","Check the end points and any excluded y."],ex:"3 sin x + 4 cos x: [\u22125, 5].",tp:"dr"},{t:"Even, odd and periodic functions",what:"A function is given. Say whether it is even, odd or neither, or find its period.",steps:["Compare f(\u2212x) with f(x) and \u2212f(x).","Find the period of each term.","Take the LCM for a sum."],ex:"sin(x/2) + cos(x/3): period 12\u03C0.",tp:"dr"},{t:"Greatest integer and fractional part",what:"An equation, a graph or a range with [x] or \uFF5Bx\uFF5D is given. Solve it, find the range or compare the values.",steps:["Put [x] = n and solve for the integer n.","Turn n \u2264 x < n + 1 into an interval.","Use \uFF5Bx\uFF5D = x \u2212 [x] \u2208 [0, 1)."],ex:"[x]\xB2 \u2212 5[x] + 6 = 0: 2 \u2264 x < 4.",tp:"dr",fig:"stgi"}],guide:{intro:"Sets, Relations and Functions give 2 to 3 questions in JEE Mains in most years. Sets and counting give a short numerical question (a Venn diagram or a power set); relations ask for the type of a relation or the count of one type; functions ask for one-one and onto, a composition, an inverse, or the domain and range. About 9 hours in 5 days is enough. The chapter is also the base for limits, calculus and probability, so the effort pays again.",plan:[["Day 1 \xB7 90 min","Sets, subsets, power set, Cartesian product, operations, De Morgan and the laws of sets."],["Day 2 \xB7 90 min","Venn diagrams, two and three set counting, exactly one and exactly two, greatest and least overlaps."],["Day 3 \xB7 105 min","Relations: the types, equivalence classes, the counting formulas and the standard relations."],["Day 4 \xB7 105 min","Functions: one-one, onto, counting functions, composition and inverse."],["Day 5 \xB7 90 min","Domain, range, graphs, even and odd, period, [x] and \uFF5Bx\uFF5D; then the Most asked types and a mock test."]],basics:["Number sets \u2115, \u2124, \u211A, \u211D and intervals.","Solving linear and quadratic inequalities.","Combinations \u207FC_r and factorials for counting.","Graphs of x\xB2, x\xB3, 1/x, |x|, \u221Ax.","Trigonometric ratios and their ranges.",'The meaning of "and", "or", "not" in logic.'],path:[{t:"Step 1 \xB7 Sets and laws (Day 1)",d:"Learn the types of sets, 2^n, the operations, the laws and De Morgan.",ready:"you can write (A \u222A B \u222A C)\u2032 and simplify A \u222A (A\u2032 \u2229 B) without a hint.",go:"formulas"},{t:"Step 2 \xB7 Venn counting (Day 2)",d:"Learn the two- and three-set formulas and the exactly-one and exactly-two rules.",ready:"you can solve a three-set problem and check that the regions add up to the union.",go:"notes"},{t:"Step 3 \xB7 Relations (Day 3)",d:"Learn the tests for reflexive, symmetric, transitive and the counting formulas.",ready:"you can give the type of a new relation with a counter-example in a minute.",go:"formulas"},{t:"Step 4 \xB7 Functions and counting (Day 4)",d:"Learn one-one, onto, the counts, composition and the inverse.",ready:"you can count the onto functions from a 5-set to a 3-set and find f\u207B\xB9 for a fraction.",go:"formulas"},{t:"Step 5 \xB7 Domain, range, graphs, [x] (Day 5)",d:"Learn the domain rules, range methods, even/odd, periods, and the graphs of [x] and \uFF5Bx\uFF5D.",ready:"you can find the domain and range of a mixed expression and the period of a sum.",go:"asked"},{t:"Step 6 \xB7 Practise, then test",d:"Practise by question type, then take the mock test.",ready:"you score 8 out of 10 in practice twice in a row.",go:"practice"}],think:["What is the topic: a set count, a relation type, a function type, or a domain and range?","Can I draw a Venn diagram or a graph first?","For counting: what are the places for one element, or the choices for one image?",'Does the question say "at least", "exactly" or "neither"?',"Is the set or domain the whole \u211D, or \u2115 or \u2124? It changes the answer.","For a relation, which property fails? Find the counter-example.","Check a boundary case: x = 0, an integer x, an empty set."],watch:["The empty set is a subset of every set, but \uFF5B\u2205\uFF5D has one element.","n(A \u222A B) needs the overlap taken off; for three sets add the triple back.","Exactly two = \u03A32 \u2212 3T, not \u03A32 \u2212 T.","A relation can be symmetric and transitive without being reflexive when an element has no pair.","One missing (a, a) is enough to make a relation not reflexive.","Check the codomain before you say a function is onto.","(g\u2218f)\u207B\xB9 = f\u207B\xB9\u2218g\u207B\xB9: the order reverses.","[\u22122.3] = \u22123 and \uFF5B\u22122.3\uFF5D = 0.7: the integer part of a negative number goes down."],myths:[["Myth: \u2205 and \uFF5B\u2205\uFF5D are the same.","Truth: \u2205 has no element; \uFF5B\u2205\uFF5D has one element, namely \u2205."],["Myth: n(A \u222A B) = n(A) + n(B).","Truth: this holds only for disjoint sets; in general subtract n(A \u2229 B)."],["Myth: A relation that is symmetric and transitive is always reflexive.","Truth: if some element has no pair it is not reflexive. On \uFF5B1, 2\uFF5D, R = \uFF5B(1, 1)\uFF5D is symmetric and transitive but misses (2, 2)."],["Myth: A \u2212 B and B \u2212 A are equal.","Truth: they are disjoint parts of A \u0394 B and equal only when A = B."],["Myth: Every function with the same rule is the same function.","Truth: the domain and codomain count too; x\xB2 on \u211D and x\xB2 on [0, \u221E) are different functions."],["Myth: A one-one function is onto.","Truth: that holds only for finite sets of equal size. e\u02E3: \u211D \u2192 \u211D is one-one and not onto."],["Myth: g\u2218f = f\u2218g.","Truth: composition is not commutative. With f = 2x + 1 and g = x\xB2, the two composites differ."],["Myth: [\u22122.3] = \u22122.","Truth: [x] is the greatest integer not above x, so [\u22122.3] = \u22123."],["Myth: The period of a sum is always the product of the periods.","Truth: it is the least common multiple, and only if one exists."],["Myth: The number of relations on a 3-set is 3\xB2 = 9.","Truth: a relation is any subset of the 9 pairs, so there are 2\u2079 = 512."]]},extra:[]}})()})();
